"use client";

import { use, useState, useEffect, useCallback } from "react";
import { Venue, Product, Category, Allergen } from "@/data/db";
import { VenueService } from "@/services/venue-service";
import { CategoryService } from "@/services/category-service";
import { ProductService } from "@/services/product-service";
import { AllergenService } from "@/services/allergen-service";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Input";
import { AuditService } from "@/services/audit-service";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/Card";
import { Switch } from "@/components/ui/Switch";
import { ArrowLeft, ArrowUp, ArrowDown, Plus, Save, Search as SearchIcon, Trash2, Edit2, Check, GripVertical, Download, X, MoreHorizontal, Star, Image as LucideImage, Globe, History, Info, Filter, Loader2, AlertTriangle } from "lucide-react";
import ImageUpload from "@/components/ui/ImageUpload";
import Link from "next/link";
import { useRouter } from "next/navigation";
import Image from "next/image";
import { cn } from "@/lib/utils";
import ProductImporter from "@/components/admin/ProductImporter";
import { AllergenManager } from "@/components/admin/AllergenManager";

// Mock Allergens List
const ALLERGENS_LIST = [
    "Gluten", "Yumurta", "S├╝t", "Hardal", "Yer F─▒st─▒─ş─▒", "Soya", "Bal─▒k", "Kabuklu Deniz ├£r├╝nleri", "Kereviz"
];

const AVAILABLE_LANGUAGES = [
    { code: 'tr', name: 'T├╝rk├ğe', flag: '­şç╣­şçÀ' },
    { code: 'en', name: 'English', flag: '­şç¼­şçğ' },
    { code: 'de', name: 'Deutsch', flag: '­şç®­şç¬' },
    { code: 'fr', name: 'Fran├ğais', flag: '­şç½­şçÀ' },
    { code: 'ar', name: 'Ïğ┘äÏ╣Ï▒Ï¿┘èÏ®', flag: '­şç©­şçĞ' },
    { code: 'ru', name: 'ºáªâªüªüº║º©º╣', flag: '­şçÀ­şç║' },
];

const AdminProductImage = ({ product, defaultImage, onClick }: { product: Product, defaultImage?: string, onClick: () => void }) => {
    const [src, setSrc] = useState(product.image || defaultImage);
    const [hasError, setHasError] = useState(false);

    useEffect(() => {
        setSrc(product.image || defaultImage);
        setHasError(false);
    }, [product.image, defaultImage]);

    return (
        <div
            className="h-24 w-24 min-w-[96px] rounded-lg bg-zinc-100 relative overflow-hidden border border-zinc-200 shadow-sm cursor-pointer hover:ring-2 hover:ring-primary/50 transition-all group-hover:scale-105"
            onClick={(e) => { e.stopPropagation(); onClick(); }}
            title="G├Ârseli d├╝zenlemek i├ğin t─▒kla"
        >
            {src && !hasError ? (
                <Image
                    src={src}
                    alt={product.name}
                    fill
                    className={cn("object-cover", src === defaultImage ? "object-contain p-2 bg-white opacity-80" : "")}
                    onError={() => {
                        if (src !== defaultImage && defaultImage) {
                            setSrc(defaultImage);
                        } else {
                            setHasError(true);
                        }
                    }}
                />
            ) : (
                <LucideImage className="h-8 w-8 absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-zinc-300" />
            )}
        </div>
    );
};

const THEME_PRESETS = [
    {
        name: "L├╝ks (FineDine Dark)",
        colors: {
            primary: "#D4AF37",
            secondary: "#27272a",
            background: "#121212",
            foreground: "#EDEDED",
            headerColor: "#121212",
            labelColor: "#D4AF37",
            cardColor: "#1E1E1E",
            cardStyle: 'modern'
        }
    },
    {
        name: "Ferah (FineDine Light)",
        colors: {
            primary: "#EA580C",
            secondary: "#FFFFFF",
            background: "#F3F4F6",
            foreground: "#111827",
            headerColor: "#FFFFFF",
            labelColor: "#EA580C",
            cardColor: "#FFFFFF",
            cardStyle: 'minimal'
        }
    },
    {
        name: "Gece Mavisi (Midnight)",
        colors: {
            primary: "#38BDF8",
            secondary: "#0F172A",
            background: "#020617",
            foreground: "#F0F9FF",
            headerColor: "#020617",
            labelColor: "#0EA5E9",
            cardColor: "#111827",
            cardStyle: 'modern'
        }
    },
    {
        name: "Organik (Do─şal)",
        colors: {
            primary: "#15803d",
            secondary: "#F0FDF4",
            background: "#FCFAF7",
            foreground: "#1c1917",
            headerColor: "#FFFFFF",
            labelColor: "#15803d",
            cardColor: "#FFFFFF",
            cardStyle: 'bordered'
        }
    }
];

export default function VenueEditor({ params }: { params: Promise<{ id: string }> }) {
    const router = useRouter();
    const unwrappedParams = use(params);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [searchQuery, setSearchQuery] = useState("");

    // Data States
    const [venueData, setVenueData] = useState<Venue | null>(null);
    const [products, setProducts] = useState<Product[]>([]);
    const [categories, setCategories] = useState<Category[]>([]);
    const [allergens, setAllergens] = useState<Allergen[]>([]);

    // Dirty State (Track changes)
    const [unsavedChanges, setUnsavedChanges] = useState<Set<string>>(new Set()); // Product IDs that changed
    const [unsavedCategoryChanges, setUnsavedCategoryChanges] = useState<Set<string>>(new Set()); // Category IDs that changed
    const [venueSettingsChanged, setVenueSettingsChanged] = useState(false);

    // UI States
    const [activeTab, setActiveTab] = useState('menu');
    const [modalTab, setModalTab] = useState<'general' | 'translations'>('general');

    // Allergen Management
    const [availableAllergens, setAvailableAllergens] = useState<string[]>(ALLERGENS_LIST);
    const [isAddingAllergen, setIsAddingAllergen] = useState(false);
    const [newAllergen, setNewAllergen] = useState("");

    const [isAllergenModalOpen, setIsAllergenModalOpen] = useState(false);
    const [editingProduct, setEditingProduct] = useState<Partial<Product> | null>(null); // For Details Modal

    // Load Data
    useEffect(() => {
        async function load() {
            setLoading(true);
            const { AuthService } = await import('@/services/auth-service');
            const profile = await AuthService.getCurrentProfile();

            if (unwrappedParams.id === 'new') {
                if (profile && profile.role !== 'SUPER_ADMIN') {
                    alert("Yeni mekan ekleme yetkiniz yok.");
                    router.push('/admin');
                    return;
                }

                const newVenueTemplate: Partial<Venue> = {
                    name: 'Yeni Mekan',
                    slug: 'yeni-mekan',
                    description: '',
                    products: [],
                    categories: [],
                    allergens: [],
                    supportedLanguages: ['tr', 'en'],
                    defaultLanguage: 'tr',
                    theme: {
                        primary: '#000000',
                        secondary: '#ffffff',
                        background: '#ffffff',
                        foreground: '#000000',
                        headerColor: '#ffffff',
                        labelColor: '#000000',
                        cardStyle: 'modern'
                    }
                };

                setVenueData(newVenueTemplate as Venue);
                setProducts([]);
                setCategories([]);

                // Load global allergens
                try {
                    const globalAllergens = await AllergenService.getAllergens();
                    setAllergens(globalAllergens);
                } catch (e) {
                    console.log("Alerjenler y├╝klenemedi", e);
                }

                setLoading(false);
                return;
            }

            if (profile && profile.role !== 'SUPER_ADMIN') {
                if (!profile.venue_ids || !profile.venue_ids.includes(unwrappedParams.id)) {
                    alert("Bu mekana eri┼şim yetkiniz yok.");
                    router.push('/admin');
                    return;
                }
            }

            const data = await VenueService.getVenueById(unwrappedParams.id);
            if (data) {
                setVenueData(data);
                setProducts(data.products || []);
                setCategories(data.categories || []);
                // Load global allergens
                const globalAllergens = await AllergenService.getAllergens();
                setAllergens(globalAllergens);
            }
            setLoading(false);
        }
        load();
    }, [unwrappedParams.id]);

    // --- Handlers ---

    const handleVenueChange = (field: keyof Venue, value: any) => {
        if (!venueData) return;

        // Update local state
        if (field === 'theme') {
            setVenueData({ ...venueData, theme: { ...venueData.theme, ...value } });
        } else {
            setVenueData({ ...venueData, [field]: value });
        }
        setVenueSettingsChanged(true);
    };

    const handleProductChange = (productId: string, field: keyof Product, value: any) => {
        setProducts(prev => prev.map(p => {
            if (p.id === productId) {
                return { ...p, [field]: value };
            }
            return p;
        }));
        setUnsavedChanges(prev => new Set(prev).add(productId));

        // If editing in modal, keep modal data in sync
        if (editingProduct && editingProduct.id === productId) {
            setEditingProduct(prev => prev ? ({ ...prev, [field]: value }) : null);
        }
    };

    const handleDeleteVenue = async () => {
        if (!venueData || !window.confirm(`"${venueData.name}" adl─▒ mekan─▒ kal─▒c─▒ olarak silmek istedi─şinize emin misiniz? Bu i┼şlem geri al─▒namaz!`)) {
            return;
        }

        try {
            setSaving(true);
            await VenueService.deleteVenue(venueData.id!);
            router.push('/admin');
        } catch (e) {
            console.error("Mekan silinirken hata:", e);
            alert("Mekan silinirken bir hata olu┼ştu.");
            setSaving(false);
        }
    };

    const handleSaveAll = async () => {
        if (!venueSettingsChanged && unsavedChanges.size === 0 && unsavedCategoryChanges.size === 0) {
            alert("Kaydedilecek yeni bir de─şi┼şiklik yok.");
            return;
        }

        // Helper to calc diff
        const calculateProductDiff = (oldP: any, newP: any) => {
            const changes: any = {};
            if (oldP.name !== newP.name) changes.name = { from: oldP.name, to: newP.name };

            // Number comparison fix
            if (Number(oldP.price) !== Number(newP.price)) changes.price = { from: oldP.price, to: newP.price };

            if (oldP.description !== newP.description) changes.description = { from: oldP.description, to: newP.description };
            if (Boolean(oldP.isAvailable) !== Boolean(newP.isAvailable)) changes.isAvailable = { from: oldP.isAvailable, to: newP.isAvailable };
            if (oldP.categoryId !== newP.categoryId) changes.categoryId = { from: oldP.categoryId, to: newP.categoryId };

            // Detailed Allergen Diff
            const oldAllergens = Array.isArray(oldP.allergens) ? oldP.allergens : [];
            const newAllergens = Array.isArray(newP.allergens) ? newP.allergens : [];

            const added = newAllergens.filter((a: string) => !oldAllergens.includes(a));
            const removed = oldAllergens.filter((a: string) => !newAllergens.includes(a));

            if (added.length > 0 || removed.length > 0) {
                changes.allergens = {
                    from: oldAllergens,
                    to: newAllergens,
                    diff: { added, removed }
                };
            }

            // Simple image check
            if (oldP.image !== newP.image) changes.image = { from: 'old_image', to: 'new_image' };

            return Object.keys(changes).length > 0 ? changes : null;
        };

        const calculateVenueDiff = (oldV: any, newV: any) => {
            const changes: any = {};
            if (oldV.name !== newV.name) changes.name = { from: oldV.name, to: newV.name };
            if (oldV.theme !== newV.theme) changes.theme = { from: oldV.theme, to: newV.theme };
            if (oldV.defaultLanguage !== newV.defaultLanguage) changes.language = { from: oldV.defaultLanguage, to: newV.defaultLanguage };
            return Object.keys(changes).length > 0 ? changes : null;
        };

        setSaving(true);
        try {
            // 1. Save Venue Settings
            if (venueSettingsChanged && venueData) {
                // Fetch current venue state for diff
                try {
                    const originalVenue = await VenueService.getVenueById(venueData.id);
                    if (originalVenue) {
                        const diff = calculateVenueDiff(originalVenue, venueData);
                        if (diff) {
                            if (diff) {
                                // Log Removed
                            }
                        }
                    }
                } catch (e) { console.error("Validation log failed", e); }

                await VenueService.updateVenue(venueData.id, {
                    name: venueData.name,
                    theme: venueData.theme,
                    coverImage: venueData.coverImage,
                    supportedLanguages: venueData.supportedLanguages,
                    defaultLanguage: venueData.defaultLanguage,
                    timezone: venueData.timezone,
                    popup_settings: venueData.popup_settings
                });
                setVenueSettingsChanged(false);
            }

            // 2. Save Modified Products
            if (unsavedChanges.size > 0) {
                const promises = Array.from(unsavedChanges).map(async (prodId) => {
                    const product = products.find(p => p.id === prodId);
                    if (product) {
                        try {
                            // Fetch original state from DB to compare
                            const originalProduct = await ProductService.getProductById(prodId);

                            const updatePayload: any = {
                                name: product.name,
                                price: product.price,
                                description: product.description,
                                categoryId: product.categoryId,
                                isAvailable: product.isAvailable,
                                isChefRecommendation: product.isChefRecommendation,
                                allergens: product.allergens,
                                image: product.image,
                                discount_type: product.discount_type,
                                discount_amount: product.discount_amount,
                                startTime: product.startTime,
                                endTime: product.endTime,
                                translations: product.translations,
                                labels: product.labels
                            };

                            // Update DB
                            await ProductService.updateProduct(prodId, updatePayload);

                        } catch (err) {
                            console.error("Product update failed for", prodId, err);
                        }
                    }
                });
                await Promise.all(promises);
                setUnsavedChanges(new Set());
            }

            // 3. Save Modified Categories
            if (unsavedCategoryChanges.size > 0) {
                const catPromises = Array.from(unsavedCategoryChanges).map(async (catId) => {
                    const cat = categories.find(c => c.id === catId);
                    if (cat) {
                        try {
                            await CategoryService.updateCategory(catId, { isAvailable: cat.isAvailable });
                        } catch (err) {
                            console.error("Category update failed for", catId, err);
                        }
                    }
                });
                await Promise.all(catPromises);
                setUnsavedCategoryChanges(new Set());
            }

            alert("T├╝m de─şi┼şiklikler ba┼şar─▒yla kaydedildi!");

        } catch (error) {
            console.error("Save failed:", error);
            alert("Kaydederken bir hata olu┼ştu.");
        } finally {
            setSaving(false);
        }
    };

    const handleCreateProduct = async () => {
        if (!venueData) return;

        // Just confirm, don't ask for name
        const confirm = window.confirm("Yeni bir taslak ├╝r├╝n olu┼şturulsun mu?");
        if (!confirm) return;

        const newProduct = {
            name: "Yeni ├£r├╝n",
            description: "├£r├╝n a├ğ─▒klamas─▒ buraya...",
            price: 150,
            isAvailable: true,
            venueId: venueData.id,
            categoryId: categories[0]?.id,
            image: ""
        };

        try {
            const created = await ProductService.createProduct(newProduct);
            if (created) {
                setProducts(prev => [...prev, created]);
            }
        } catch (err) {
            console.error(err);
            alert("├£r├╝n olu┼şturulamad─▒.");
        }
    };

    // Category Management
    const [editingCategory, setEditingCategory] = useState<Category | null>(null);
    const [isCategoryModalOpen, setIsCategoryModalOpen] = useState(false);
    const [categoryModalTab, setCategoryModalTab] = useState<'general' | 'translations'>('general');

    const handleCreateCategory = () => {
        if (!venueData) return;
        setEditingCategory({ id: 'new', name: '', translations: {} } as any);
        setCategoryModalTab('general');
        setIsCategoryModalOpen(true);
    };

    const handleEditCategory = (cat: Category) => {
        setEditingCategory({ ...cat, translations: cat.translations || {} });
        setCategoryModalTab('general');
        setIsCategoryModalOpen(true);
    };

    const handleSaveCategory = async () => {
        if (!editingCategory) return;
        try {
            if (editingCategory.id === 'new') {
                const created = await CategoryService.createCategory({
                    venueId: venueData!.id,
                    name: editingCategory.name,
                    translations: editingCategory.translations,
                    image: editingCategory.image,
                    coverImage: editingCategory.coverImage
                });
                if (created) {
                    setCategories(prev => [...prev, created]);
                }
            } else {
                // Update
                const catId = editingCategory.id || '';

                await CategoryService.updateCategory(catId, {
                    name: editingCategory.name,
                    translations: editingCategory.translations,
                    image: editingCategory.image,
                    coverImage: editingCategory.coverImage
                });

                // Update local state
                setCategories(prev => prev.map(c => c.id === editingCategory.id ? (editingCategory as Category) : c));
            }
            setIsCategoryModalOpen(false);
        } catch (e) {
            console.error(e);
            alert("Kategori kaydedilirken hata olu┼ştu.");
        }
    };

    const handleDeleteCategory = async (catId: string) => {
        const hasProducts = products.some(p => p.categoryId === catId);
        if (hasProducts) {
            alert("Bu kategoriye ait ├╝r├╝nler var. L├╝tfen ├Ânce ├╝r├╝nleri silin veya ta┼ş─▒y─▒n.");
            return;
        }

        if (!window.confirm("Bu kategoriyi silmek istedi─şinize emin misiniz?")) return;

        try {
            await CategoryService.deleteCategory(catId);
            setCategories(prev => prev.filter(c => c.id !== catId));
        } catch (e) {
            console.error(e);
            alert("Kategori silinirken hata olu┼ştu.");
        }
    };

    const handleCategoryChange = (catId: string, field: keyof Category, value: any) => {
        // Optimistic UI update only. Will be saved on "Kaydet" click.
        setCategories(prev => prev.map(c =>
            c.id === catId ? { ...c, [field]: value } : c
        ));
        setUnsavedCategoryChanges(prev => new Set(prev).add(catId));
    };

    const handleMoveCategory = async (index: number, direction: 'up' | 'down') => {
        const newCategories = [...categories];
        if (direction === 'up' && index > 0) {
            const temp = newCategories[index - 1];
            newCategories[index - 1] = newCategories[index];
            newCategories[index] = temp;
        } else if (direction === 'down' && index < newCategories.length - 1) {
            const temp = newCategories[index + 1];
            newCategories[index + 1] = newCategories[index];
            newCategories[index] = temp;
        } else {
            return;
        }

        setCategories(newCategories);
        try {
            await CategoryService.updateCategoryOrder(newCategories.map(c => c.id));
        } catch (e) {
            console.error(e);
            alert("Kategori s─▒ralamas─▒ g├╝ncellenemedi.");
        }
    };

    const handleDeleteProduct = async (prodId: string) => {
        if (!window.confirm("Bu ├╝r├╝n├╝ silmek istedi─şinize emin misiniz?")) return;
        try {
            await ProductService.deleteProduct(prodId);
            setProducts(prev => prev.filter(p => p.id !== prodId));
            setUnsavedChanges(prev => {
                const next = new Set(prev);
                next.delete(prodId);
                return next;
            });
        } catch (e) {
            console.error(e);
            alert("├£r├╝n silinemedi.");
        }
    };

    const handleImportProducts = async (importedData: any[]) => {
        if (!venueData) return;
        setLoading(true);
        try {
            // Find or create categories first
            const catMap = new Map<string, string>(); // Name -> ID
            categories.forEach(c => catMap.set(c.name.toLowerCase(), c.id));

            for (const item of importedData) {
                const catName = (item.categoryName || "Genel").toLowerCase();
                let categoryId = catMap.get(catName);
                if (!categoryId) {
                    // Create new category if not exists
                    const newCat = await CategoryService.createCategory({ venueId: venueData!.id, name: item.categoryName || "Genel" });
                    if (newCat && newCat.id) {
                        categoryId = newCat.id;
                        catMap.set(catName, newCat.id);
                        // Update local state immediately so next items find it
                        setCategories(prev => [...prev, newCat]);
                    }
                }

                if (!categoryId) continue; // Should not happen

                // Check if it is UPDATE (has ID) or CREATE
                if (item.id) {
                    await ProductService.updateProduct(item.id, {
                        name: item.name,
                        description: item.description,
                        price: item.price,
                        categoryId: categoryId, // Allow category change
                        image: item.image,
                        isAvailable: item.isAvailable,
                        isChefRecommendation: item.isChefRecommendation,
                        allergens: item.allergens,
                        discount_type: item.discount_type,
                        discount_amount: item.discount_amount,
                        startTime: item.startTime,
                        endTime: item.endTime
                    });
                } else {
                    await ProductService.createProduct({
                        venueId: venueData.id,
                        categoryId: categoryId,
                        name: item.name,
                        description: item.description,
                        price: item.price,
                        image: item.image,
                        isAvailable: item.isAvailable,
                        isChefRecommendation: item.isChefRecommendation,
                        allergens: item.allergens,
                        discount_type: item.discount_type,
                        discount_amount: item.discount_amount,
                        startTime: item.startTime,
                        endTime: item.endTime
                    });
                }
            }

            // Refresh Products
            const updatedVenue = await VenueService.getVenueById(venueData.id);
            if (updatedVenue) {
                setProducts(updatedVenue.products);
            }
            alert("─░├ğe akt─▒rma/g├╝ncelleme tamamland─▒.");

        } catch (err) {
            console.error(err);
            alert("─░├ğe akt─▒rma s─▒ras─▒nda bir hata olu┼ştu: " + err);
        } finally {
            setLoading(false);
        }
    };

    const handleExportProducts = async () => {
        // Dynamic import to avoid large bundle size on initial load if not needed
        const XLSX = await import("xlsx");

        const exportData = products.map(p => {
            const catName = categories.find(c => c.id === p.categoryId)?.name || "Genel";
            return {
                "ID": p.id, // Export ID for update capability
                "├£r├╝n Ad─▒": p.name,
                "├£r├╝n Ad─▒ (EN)": p.translations?.en?.name || "",
                "A├ğ─▒klama": p.description,
                "A├ğ─▒klama (EN)": p.translations?.en?.description || "",
                "Fiyat": p.price,
                "Kategori": catName,
                "Kategori (EN)": categories.find(c => c.id === p.categoryId)?.translations?.en?.name || "",
                "Alerjenler": p.allergens ? p.allergens.join(", ") : "",
                "┼Şef": p.isChefRecommendation ? "Evet" : "Hay─▒r",
                "─░ndirim Tipi": p.discount_type || "",
                "─░ndirim De─şeri": p.discount_amount || "",
                "Ba┼şlama Saati": p.startTime || "",
                "Biti┼ş Saati": p.endTime || "",
                "Durum": p.isAvailable ? "Aktif" : "Pasif",
                "G├Ârsel Dosya Ad─▒": p.image ? p.image : "" // Export current URL as filename reference
            };
        });

        const ws = XLSX.utils.json_to_sheet(exportData);
